1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      /* The color is the content here, so keep it; the stroke guarantees the shape */
60	      .circle svg {
61	        forced-color-adjust: none;
62	        color: var(--fg);
63	      }
64	      svg circle {
65	        stroke: CanvasText;
66	        stroke-width: 2;
67	      }
68	    }
69	    body {
70	      min-height: 100vh;
71	      min-height: 100dvh;
72	      display: grid;
73	      place-items: center;
74	      padding: 1rem;
75	      background: var(--bg);
76	      color: var(--text);
77	      font-family: system-ui, -apple-system, sans-serif;
78	    }
79	    main {
80	      width: 100%;
81	      display: flex;
82	      flex-direction: column;
83	      align-items: center;
84	      text-align: center;
85	    }
86	    .circle {
87	      display: block;
88	      width: min(360px, 100%, 60vh);
89	      aspect-ratio: 1;
90	      border: 0;
91	      border-radius: 50%;
92	      background: none;
93	      color: var(--fg);
94	      cursor: pointer;
95	      touch-action: manipulation;
96	      -webkit-tap-highlight-color: transparent;
97	      -webkit-user-select: none;
98	      user-select: none;
99	      -webkit-touch-callout: none;
100	      transition: color 0.4s;
101	      min-height: 48px;
102	      min-width: 48px;
103	    }
104	    .no-transition,
105	    .no-transition svg {
106	      transition: none !important;
107	    }
108	    .circle:focus-visible {
109	      outline: 3px solid currentColor;
110	      outline-offset: 12px;
111	    }
112	    svg {
113	      display: block;
114	      width: 100%;
115	      height: 100%;
116	      overflow: visible;
117	      opacity: 0.85;
118	      filter: var(--drop);
119	      transition: opacity 0.3s;
120	    }
121	    .circle:active svg,
122	    .circle:focus-visible svg {
123	      opacity: 1;
124	    }
125	    @keyframes pulse {
126	      0% {
127	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
128	      }
129	      100% {
130	        filter: var(--drop) drop-shadow(0 0 0 transparent);
131	      }
132	    }
133	    @media (hover: hover) {
134	      .circle:hover svg {
135	        opacity: 1;
136	      }
137	    }
138	    @media (prefers-reduced-motion: no-preference) {
139	      svg {
140	        transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s;
141	      }
142	      .circle:focus-visible svg {
143	        transform: scale(1.05);
144	      }
145	      .circle:active svg {
146	        transform: scale(0.97);
147	      }
148	      .circle.color-changed svg {
149	        animation: pulse 0.5s ease-out;
150	      }
151	    }
152	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
153	      .circle:hover:not(:active) svg {
154	        transform: scale(1.05);
155	      }
156	    }
157	    .visually-hidden {
158	      position: absolute;
159	      width: 1px;
160	      height: 1px;
161	      overflow: hidden;
162	      clip-path: inset(50%);
163	      white-space: nowrap;
164	    }
165	    .status {
166	      margin-top: 2rem;
167	      font-weight: 600;
168	    }
169	    .hint {
170	      margin-top: 0.25rem;
171	      font-size: 0.875rem;
172	      line-height: 1.75;
173	      text-wrap: balance;
174	    }
175	    .help-button {
176	      margin-left: 0.5rem;
177	      display: inline-block;
178	      width: 1.5rem;
179	      height: 1.5rem;
180	      border-radius: 50%;
181	      background: var(--kbd-bg);
182	      border: 1px solid var(--text);
183	      color: var(--text);
184	      cursor: pointer;
185	      font: inherit;
186	      font-size: 0.75rem;
187	      font-weight: bold;
188	      line-height: 1;
189	      text-align: center;
190	      vertical-align: middle;
191	      touch-action: manipulation;
192	      transition: background-color 0.2s, color 0.2s;
193	    }
194	    .help-button:focus-visible {
195	      outline: 2px solid currentColor;
196	      outline-offset: 2px;
197	    }
198	    @media (hover: hover) {
199	      .help-button:hover {
200	        background: var(--text);
201	        color: var(--bg);
202	      }
203	    }
204	    .keys {
205	      display: none;
206	    }
207	    .keys.visible {
208	      display: inline;
209	    }
210	    @media (hover: none) and (pointer: coarse) {
211	      .hint .keys {
212	        display: none !important;
213	      }
214	      .help-button {
215	        display: none;
216	      }
217	    }
218	    kbd {
219	      display: inline-block;
220	      padding: 0.125rem 0.375rem;
221	      background: var(--kbd-bg);
222	      border: 1px solid transparent;
223	      border-radius: 0.25rem;
224	      font-family: monospace;
225	      font-size: 0.75em;
226	      line-height: 1.2;
227	    }
228	  </style>
229	</head>
230	<body>
231	  <main>
232	    <h1 class="visually-hidden">Animated Circle</h1>
233	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
234	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
235	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
236	      </svg>
237	    </button>
238	    <p class="status" id="status" role="status" aria-live="polite">Blue</p>
239	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
240	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
241	  </main>
242	  <script>
243	    const config = {
244	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
245	      storageKey: 'circle-color',
246	      hapticDuration: 50,
247	      longPressDuration: 500,
248	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
249	    };
250	
251	    const DOM = {
252	      button: document.querySelector('.circle'),
253	      status: document.querySelector('.status'),
254	      helpButton: document.querySelector('.help-button'),
255	      keyHint: document.querySelector('.keys'),
256	      verbSpan: document.querySelector('.verb'),
257	      doubleVerbSpan: document.querySelector('.double-verb'),
258	    };
259	
260	    const state = {
261	      index: 0,
262	      shiftHeld: false,
263	      hoverCapable: true,
264	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
265	      hoverQuery: matchMedia('(hover: none)'),
266	      longPressTimer: null,
267	      longPressed: false,
268	      pointerType: '',
269	    };
270	
271	    function loadColor() {
272	      try {
273	        return localStorage.getItem(config.storageKey);
274	      } catch {
275	        return null;
276	      }
277	    }
278	
279	    function saveColor(color) {
280	      try {
281	        localStorage.setItem(config.storageKey, color);
282	      } catch {}
283	    }
284	
285	    function applyColor() {
286	      const color = config.colors[state.index];
287	      // The first color is the :root default, so it needs no attribute
288	      if (state.index === 0) delete DOM.button.dataset.color;
289	      else DOM.button.dataset.color = color;
290	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
291	    }
292	
293	    function syncFromStorage(color = loadColor()) {
294	      const index = config.colors.indexOf(color);
295	      state.index = index === -1 ? 0 : index;
296	      applyColor();
297	    }
298	
299	    // acknowledge: give feedback even when the color is already the requested one
300	    function setIndex(next, { haptic = false, acknowledge = false } = {}) {
301	      const changed = next !== state.index;
302	      if (!changed && !acknowledge) return;
303	      if (changed) {
304	        state.index = next;
305	        applyColor();
306	        saveColor(config.colors[state.index]);
307	      }
308	
309	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
310	
311	      if (state.reducedMotion.matches) return;
312	      DOM.button.classList.remove('color-changed');
313	      void DOM.button.offsetWidth;
314	      DOM.button.classList.add('color-changed');
315	    }
316	
317	    function changeColor(step) {
318	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
319	    }
320	
321	    function updateDeviceVerbs() {
322	      state.hoverCapable = !state.hoverQuery.matches;
323	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
324	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
325	    }
326	
327	    function toggleKeyHintVisibility() {
328	      const expanded = DOM.keyHint.classList.toggle('visible');
329	      DOM.helpButton.setAttribute('aria-expanded', expanded);
330	    }
331	
332	    function syncKeyHint() {
333	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
334	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
335	    }
336	
337	    function handleKeyDown(event) {
338	      if (event.key === 'Enter' || event.key === ' ') {
339	        if (!event.repeat) state.shiftHeld = event.shiftKey;
340	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
341	        return;
342	      }
343	
344	      if (event.altKey || event.ctrlKey || event.metaKey) return;
345	
346	      if (event.key in config.keySteps) {
347	        event.preventDefault();
348	        changeColor(config.keySteps[event.key]);
349	      } else if (event.key === 'Home') {
350	        event.preventDefault();
351	        setIndex(0, { haptic: true });
352	      } else if (event.key === 'End') {
353	        event.preventDefault();
354	        setIndex(config.colors.length - 1, { haptic: true });
355	      }
356	    }
357	
358	    function handleEscape(event) {
359	      if (event.key !== 'Escape' || state.hoverCapable) return;
360	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
361	    }
362	
363	    // Initialize
364	    syncFromStorage();
365	
366	    // Wait two frames to ensure layout is complete before enabling transitions
367	    requestAnimationFrame(() => requestAnimationFrame(() => {
368	      DOM.button.classList.remove('no-transition');
369	    }));
370	
371	    updateDeviceVerbs();
372	    syncKeyHint();
373	    // e.g. a tablet gaining or losing a trackpad/keyboard
374	    state.hoverQuery.addEventListener('change', () => {
375	      updateDeviceVerbs();
376	      syncKeyHint();
377	    });
378	
379	    // Event listeners
380	    function clearLongPressTimer() {
381	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
382	      state.longPressTimer = null;
383	    }
384	
385	    function attachEventListeners() {
386	      DOM.button.addEventListener('keydown', handleKeyDown);
387	      DOM.button.addEventListener('keyup', (event) => {
388	        if (event.key === ' ') state.shiftHeld = event.shiftKey;
389	      });
390	      DOM.button.addEventListener('blur', () => {
391	        state.shiftHeld = false;
392	        clearLongPressTimer();
393	      });
394	      DOM.button.addEventListener('pointerdown', (event) => {
395	        clearLongPressTimer();
396	        state.longPressed = false;
397	        state.pointerType = event.pointerType;
398	        if (!event.isPrimary || event.button !== 0) return;
399	        state.longPressTimer = setTimeout(() => {
400	          state.longPressTimer = null;
401	          state.longPressed = true;
402	          setIndex(0, { haptic: true, acknowledge: true });
403	        }, config.longPressDuration);
404	      }, { passive: true });
405	      DOM.button.addEventListener('contextmenu', (event) => {
406	        if (state.pointerType === 'mouse') {
407	          clearLongPressTimer();
408	        } else if (state.longPressTimer || state.longPressed) {
409	          event.preventDefault();
410	        }
411	      });
412	      DOM.button.addEventListener('pointerup', clearLongPressTimer, { passive: true });
413	      DOM.button.addEventListener('pointercancel', clearLongPressTimer, { passive: true });
414	      DOM.button.addEventListener('pointerleave', clearLongPressTimer, { passive: true });
415	      DOM.button.addEventListener('click', (event) => {
416	        clearLongPressTimer();
417	        const afterLongPress = state.longPressed && event.detail !== 0;
418	        state.longPressed = false;
419	        const reverse = event.shiftKey || state.shiftHeld;
420	        state.shiftHeld = false;
421	        if (afterLongPress || event.detail > 1) return;
422	        changeColor(reverse ? -1 : 1);
423	      });
424	      DOM.button.addEventListener('dblclick', () => {
425	        setIndex(0, { haptic: true, acknowledge: true });
426	      });
427	      DOM.button.addEventListener('animationend', () => {
428	        DOM.button.classList.remove('color-changed');
429	      });
430	
431	      DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
432	      addEventListener('keydown', handleEscape);
433	    }
434	
435	    attachEventListeners();
436	
437	    addEventListener('storage', (event) => {
438	      // Sync if changed key matches or if entire storage was cleared (key === null)
439	      if (event.key !== config.storageKey && event.key !== null) return;
440	      syncFromStorage(event.newValue);
441	    });
442	    // Storage events are not delivered while the page sits in the bfcache
443	    addEventListener('pageshow', (event) => {
444	      if (event.persisted) syncFromStorage();
445	    });
446	  </script>
447	</body>
448	</html>
