  if (!event.isPrimary || event.button !== 0) return;
  state.pressX = event.clientX;
  state.pressY = event.clientY;
  state.longPressTimer = setTimeout(() => {
    state.longPressTimer = null;
    state.longPressed = true;
    setIndex(0, { haptic: true, acknowledge: true });
  }, config.longPressDuration);
}, { passive: true });
// Touch pointers are captured, so a finger sliding away never fires pointerleave
DOM.button.addEventListener('pointermove', (event) => {
  if (!state.longPressTimer) return;
  const distance = Math.hypot(event.clientX - state.pressX, event.clientY - state.pressY);
  if (distance > config.longPressTolerance) clearLongPressTimer();
}, { passive: true });

